return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-28T00:05:24+00:00','po-revision-date'=>'2026-09-28T00:05:24+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Temeljno izdanje ponovno izgrađenog alata Page Builder Sandwich: zaslon s postavkama i odjeljkom O programu, izlazni sloj pročelja bez SEO otiska i jedan uzorak sadržajnog bloka.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI pružatelji usluga','The makers of ChatGPT. A good all-rounder.'=>'Tvorci aplikacije ChatGPT. Dobar svestrani alat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvorci sustava Claude. Snažni u pisanju i opreznom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Googleovi modeli Gemini. Brzi i povoljni.','A European AI company with fast, inexpensive models.'=>'Europska AI tvrtka s brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Jeftini modeli koji su dobri u pisanju i kodiranju.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih pružatelja usluga.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi poput OpenAI-jevog API-ja, uključujući model koji se izvodi na vašem vlastitom računalu ili poslužitelju.','General (used when nothing more specific is set)'=>'Općenito (koristi se kada ništa specifičnije nije postavljeno)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prijevod','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate dopuštenje za pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ove postavke dijeli svaki dodatak koji ih koristi: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši su ključevi šifrirani u bazi podataka ove web-lokacije i šalju se samo odabranom davatelju usluga – nikada nama.','Step 1 of 2: choose an AI provider'=>'1. korak od 2: odaberite AI davatelja usluge','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Vi donosite svoj vlastiti ključ, pa stoga davatelju usluga plaćate izravno za ono što potrošite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionira; kasnije možete dodati još.','Next'=>'Sljedeće','Step 2 of 2: connect %s'=>'2. korak od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu svoje usluge kompatibilne s OpenAI, koja završava s /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili izradite besplatan račun).','the %s API keys page'=>'stranica za %s API ključeve','Create a new key and copy it.'=>'Stvorite novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Zalijepite ga u nastavku i pritisnite "Spremi i testiraj". Šaljemo jedan mali zahtjev kako bismo provjerili radi li.','Most providers need a little credit on the account before a key works: %s.'=>'Većina davatelja usluga treba malo kredita na računu prije nego što ključ počne raditi: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Odaberite drugog pružatelja usluga','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Spremljeni ključ završava s …%s — zalijepite novi da biste ga zamijenili','Key (optional)'=>'Ključ (izborno)','API key'=>'API ključ','Save and test'=>'Spremi i testiraj','Providers'=>'Pružatelji usluga','Provider'=>'Pružatelj usluga','Status'=>'Status','Key'=>'Ključni','Get a key'=>'Nabavite ključ','Test'=>'Test','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Spremljeno novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovno unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Spremljeni ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno.','Not connected'=>'Nije povezano','Connected — last test passed %s'=>'Povezano – zadnji test uspješan %s','Last test failed: %s'=>'Posljednji test nije uspio: %s','Connected — not tested yet'=>'Povezano – još nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Popis uključuje svaki model koji vaš ključ može koristiti, učitan uživo od davatelja.','— Recommended for the provider —'=>'— Preporučeno za davatelja usluge —','Save models'=>'Spremi modele','Refresh the model lists from the providers'=>'Osvježite popise modela od davatelja usluga','best quality'=>'najbolja kvaliteta','lowest cost'=>'najniža cijena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Model je izašao danas? Zalijepite njegov točan naziv kako biste ga odmah počeli koristiti.','Model name'=>'Naziv modela','Add model'=>'Dodaj model','Recommended models list'=>'Popis preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Popis preporučenih modela nije mogao biti potvrđen, stoga se preporuke ne prikazuju. Ponovno instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Popis koji se koristi objavljen je %s. Svako ažuriranje dodatka donosi novi.','Also check Zinn Digital® once a day for an updated list.'=>'Također provjerite Zinn Digital® jednom dnevno za ažurirani popis.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtjev za preuzimanje: bez ključa, bez adrese web-mjesta, ništa o vašem sadržaju. Popis je potpisan, a popis koji ne prođe provjeru potpisa se zanemaruje.','Last checked %1$s: %2$s.'=>'Zadnja provjera %1$s: %2$s.','Save, and check now if turned on'=>'Spremite i provjerite odmah ako je uključeno','a newer list was installed'=>'noviji popis je instaliran','already up to date'=>'već ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije prošlo provjeru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Nije se moguće povezati sa Zinn Digital®; trenutna lista ostaje u upotrebi','turned off'=>'isključeno','Open'=>'Otvori','Check their status page'=>'Provjerite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite stranicu za naplatę','Open your API keys page'=>'Otvorite stranicu s API ključevima','Open the AI settings'=>'Otvorite AI postavke','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dopuštenje za to.','Unknown provider.'=>'Nepoznati davatelj usluga.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primjer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne izgleda kao API ključ. Kopirajte ga ponovno, bez razmaka.','Paste your API key first.'=>'Prvo zalijepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su spremljeni.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite točan naziv modela, na primjer kako je navedeno u dokumentaciji davatelja usluge.','Added %s. Choose it under "Which model to use".'=>'Dodano %s. Odaberite ga pod "Koji model koristiti".','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se popis koji je došao s dodacima.','Checked: %s.'=>'Provjereno: %s.','Model lists refreshed.'=>'Popisi modela su osvježeni.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ je spremila novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovno unesite ključ u AI postavkama.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš spremljeni AI ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno u postavkama umjetne inteligencije.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI još nije postavljen. Dodajte ključ za AI pružatelja usluga u postavkama za AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Za ovaj zadatak nije odabran nijedan model. Odaberite ga u postavkama umjetne inteligencije.','That AI provider is not supported by this version of the plugin.'=>'Taj pružatelj usluge umjetne inteligencije nije podržan u ovoj verziji dodatka.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ova web-lokacija nije mogla dosegnuti vašu AI uslugu. Provjerite radi li i je li njegova adresa dostupna s vašeg web-poslužitelja (usluga na vašem vlastitom računalu nije dostupna s hostirane web-lokacije).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ova stranica nije mogla dosegnuti %s. Provjerite njihovu stranicu statusa; ako rade, vaš poslužitelj možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš račun nema preostalog kredita ili kvote. Dodajte kredit ili povećajte ograničenje na svom računu kod njih, a zatim pokušajte ponovo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno upisan, opozvan ili je istekao. Stvorite novi ključ i zalijepite ga ovdje.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtjev za vaš ključ. Ključ možda nema pristup ovom modelu ili značajci, ili je vaš račun potrebno verificirati.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od %2$s za vaš ključ. Odaberite drugi model u postavkama umjetne inteligencije.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Vaš plan %2$s ne uključuje model "%1$s". Odaberite drugi model u AI postavkama ili nadogradite svoj plan.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može slati zahtjeve. Pričekajte minutu i pokušajte ponovno ili povećajte ograničenje brzine s njima.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutačno ima problema (prekid rada ili preopterećenje na njihovoj strani). Vaše postavke su u redu. Pokušajte ponovno uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Zahtjev za umjetnu inteligenciju nije uspio iz razloga koji nismo mogli utvrditi. Pokušajte ponovno; ako se to nastavi događati, obratite se podršci s detaljima u nastavku.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pružatelj usluge umjetne inteligencije odgovorio je u obliku koji ovaj dodatak nije mogao pročitati. Pokušajte ponovno; ako se to nastavi događati, odaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno s OpenAI)','Save a key for this provider first.'=>'Najprije spremite ključ za ovog davatelja usluga.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali pružatelj usluge za njega ne navodi nijedan tekstualni model. Dodajte model sami u nastavku.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s se odazvao koristeći %2$s. Vaše AI značajke spremne su za korištenje.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisnička uloga nema dopuštenje za korištenje umjetne inteligencije na ovoj web-lokaciji. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegla mjesečno ograničenje potrošnje na AI. Administrator ga može povećati u postavkama za AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegnula mjesečni limit AI zahtjeva. Administrator ga može povećati u postavkama za AI.','Usage and cost'=>'Korištenje i trošak','The log, limits and role permissions apply to AI used through: %s.'=>'Zapisnik, ograničenja i dozvole uloga primjenjuju se na AI koji se koristi putem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na temelju objavljenih cijena; model bez poznate cijene računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovaj mjesec: %1$s zahtjeva, oko %2$s.','When'=>'Kada','Who'=>'Tko','Used for'=>'Koristi se za','Model'=>'Model','Tokens in / out'=>'Tokeni (ulaz / izlaz)','About'=>'O programu','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još uvijek nisu podneseni nikakvi zahtjevi za umjetnu inteligenciju.','Done'=>'Gotovo','Limits and permissions'=>'Ograničenja i dozvole','Monthly spending limit (US dollars)'=>'Mjesečni limit potrošnje (US dolara)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. AI se zaustavlja do kraja mjeseca kada približni trošak dosegne tu vrijednost.','Monthly request limit'=>'Mjesečno ograničenje zahtjeva','Leave empty for no limit.'=>'Ostavite prazno za bez ograničenja.','Who may use AI'=>'Tko može koristiti AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa kako biste omogućili svima koji mogu koristiti značajke dodatka da koriste umjetnu inteligenciju. Administratori je uvijek mogu koristiti.','Save limits and permissions'=>'Spremi ograničenja i dozvole','Limits and permissions saved.'=>'Ograničenja i dozvole su spremljeni.','Security error, please refresh the page and try again.'=>'Sigurnosna pogreška, osvježite stranicu i pokušajte ponovno.','Missing newsletter settings. Please contact the admin.'=>'Nedostaju postavke biltena. Obratite se administratoru.','Invalid newsletter settings. Please contact the admin.'=>'Nevažeće postavke biltena. Obratite se administratoru.','Invalid email address.'=>'Nevažeća adresa e-pošte.','Too many attempts. Please try again in a few minutes.'=>'Previše pokušaja. Molimo pokušajte ponovno za nekoliko minuta.','Something went wrong. Please contact the admin.'=>'Nešto je pošlo po zlu. Molimo kontaktirajte administratora.','Map'=>'Mapirajte','Background video'=>'Pozadinski videozapis','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: pohranjene %2$d datoteke fontova, stilski naziv %3$s','That family is not stored.'=>'Ta obitelj nije spremljena.','Removed.'=>'Uklonjeno.','That is not a valid font family name.'=>'To nije valjani naziv obitelji fontova.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts nije vratio tu obitelj. Provjerite naziv i pokušajte ponovno.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Datoteke fontova nije bilo moguće preuzeti ili spremiti. Provjerite može li se pisati u mapu uploads.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Pogled stilskih definicija fontova nije bilo moguće spremiti. Provjerite ima li mapa uploads dozvolu za pisanje.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripte administratorskog zaslona nedostaju u ovoj kopiji dodatka. Ponovno je instalirajte iz objavljenog paketa.','This screen needs JavaScript.'=>'Ovaj zaslon zahtijeva JavaScript.','Languages'=>'Jezici','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks mora sadržavati od 1 do 8 malih slova ili znamenaka, započinjati slovom i ne smije nositi naziv dodatka.','You are not allowed to edit this item.'=>'Nije vam dopušteno uređivanje ove stavke.','You are not allowed to do this.'=>'Nije vam dopušteno ovo učiniti.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Sigurni način rada isključen je jer se više ne podudara s vašom prijavom. Ponovo učitajte stranicu.','Only an administrator can use safe mode.'=>'Samo administrator može koristiti siguran način rada.','Safe mode needs a normal browser login.'=>'Siguran način rada zahtijeva običnu prijavu putem preglednika.','Safe mode could not be set up.'=>'Siguran način rada nije se mogao postaviti.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Siguran način rada zahtijeva pristup za pisanje u mapu wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Siguran način rada nije mogao zapisati u mapu wp-content/mu-plugins.','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Ta stranica ne postoji ili je izbrisana.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Žao nam je, nemate dopuštenje za uređivanje ove stavke u aplikaciji Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Sandwich Studio nije izgrađen. Ponovno instalirajte dodatak.','Add title'=>'Dodaj naslov','Type / to choose a block'=>'Unesite / za odabir bloka','Loading Sandwich Studio…'=>'Učitavanje alata Sandwich Studio…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio zahtijeva JavaScript. Umjesto toga upotrijebite obični uređivač.','Edit “%s” with Sandwich Studio'=>'Uredi „%s“ pomoću alata Sandwich Studio','Edit with Sandwich Studio'=>'Uredi pomoću aplikacije Sandwich Studio','Blank canvas'=>'Prazno platno','Part of the message telling the user what they should receive via email.a license key'=>'licencni ključ','A user has not yet been associated with the license, which is necessary to prevent unauthorized activation. To assign the license to your user, you agree to share your WordPress user\'s full name and 